SET LOCAL statement_timeout = '180s';

DO $$ BEGIN
  IF (select max(migration_number) from public.greanlean_migration_ledger where result='applied') <> '0039' THEN RAISE EXCEPTION 'migration head mismatch'; END IF;
  IF (select count(*) from public.dpp_passport where passport_identifier=any(array['DPP-GLR-EBIKE-000001','DPP-GLR-EBIKE-000002','DPP-GLR-EBIKE-000003','DPP-GLR-EBIKE-000004','DPP-GLR-EBIKE-000005','DPP-GLR-EBIKE-000006','DPP-GLR-EBIKE-000007','DPP-GLR-EBIKE-000008','DPP-GLR-EBIKE-000009','DPP-GLR-EBIKE-000010','DPP-GLR-EBIKE-000011','DPP-GLR-EBIKE-000012','DPP-GLR-EBIKE-000013','DPP-GLR-EBIKE-000014','DPP-GLR-EBIKE-000015','DPP-GLR-EBIKE-000016','DPP-GLR-EBIKE-000017','DPP-GLR-EBIKE-000018','DPP-GLR-EBIKE-000019','DPP-GLR-EBIKE-000020','DPP-GLR-EBIKE-000021','DPP-GLR-EBIKE-000022']::text[])) <> 22 THEN RAISE EXCEPTION 'legacy count mismatch'; END IF;
  IF (select count(*) from public.dpp_passport where passport_identifier=any(array['DPP-GLR-LMT-000001','DPP-GLR-LMT-000002','DPP-GLR-LMT-000003','DPP-DEMO-ESS-000001','DPP-DEMO-TEX-000001','DPP-DEMO-CE-000001','DPP-DEMO-BLD-000001','DPP-DEMO-HW-000001']::text[])) <> 0 THEN RAISE EXCEPTION 'approved DPP collision'; END IF;
